function testList() {
  const saved = {}
  const storage = {
    getItem: key => (key in saved ? saved[key] : null),
    setItem: (key, value) => { saved[key] = String(value) }
  }
  addToList(storage, "signups", { id: 13, cancelCode: "x" })
  console.log(JSON.stringify(loadList(storage, "signups")))
}

function loadList(storage, key) {
  const text = storage.getItem(key)
  if (text === null) {
    return []
  }
  return JSON.parse(text)
}

function addToList(storage, key, item) {
  const list = loadList(storage, key)
  list.push(item)
  storage.setItem(key, JSON.stringify(list))
}
